import React, { useState, useEffect } from 'react';
import { Link, useNavigate, useLocation } from 'react-router-dom';
import ApiService from '../../Services/ApiService';
import { toast } from 'react-toastify';

export default function SellerReelsAll() {
    const navigate = useNavigate();
    const location = useLocation();
    const [reels, setReels] = useState([]);
    const [loading, setLoading] = useState(true);
    const [productNames, setProductNames] = useState({});
    const [filters, setFilters] = useState({
        title: '',
        category: '',
        date: '',
        product: '',
        status: ''
    });
    const [appliedFilters, setAppliedFilters] = useState({
        title: '',
        category: '',
        date: '',
        product: '',
        status: ''
    });
    // Pagination state
    const [currentPage, setCurrentPage] = useState(1);
    const pageSize = 10;

    useEffect(() => {
        if (window.lucide) {
            window.lucide.createIcons();
        }
        if (window.RemixIcon) {
            window.RemixIcon.init();
        }
        const params = new URLSearchParams(location.search);
        const initialProduct = params.get('product') || '';
        if (initialProduct) {
            setFilters({ ...filters, product: initialProduct });
            setAppliedFilters({ ...appliedFilters, product: initialProduct });
            loadSellerReelsWithFilters();
        } else {
            loadSellerReels();
        }
    }, [location.search]);

    // Reset pagination when reels change
    useEffect(() => {
        setCurrentPage(1);
    }, [reels]);

    const loadSellerReels = async () => {
        try {
            setLoading(true);
            
            // Get the vendor ID from the authenticated user
            const user = JSON.parse(localStorage.getItem('studioUser'));
            const vendorId = user?.vendor_id;
            
            if (!vendorId) {
                toast.error('Unable to load reels: User not authenticated');
                setLoading(false);
                return;
            }
            
            // Get seller reels from API
            const response = await ApiService.getSellerReels(vendorId);
            
            if (response.success) {
                // Load product names for all reels
                await loadProductNames(response.data);
                
                // Set reels directly without grouping
                setReels(response.data);
            }
            setLoading(false);
        } catch (error) {
            console.error('Error loading seller reels:', error);
            toast.error('Failed to load reels: ' + error.message);
            setLoading(false);
        }
    };

    const loadSellerReelsWithFilters = async () => {
        try {
            setLoading(true);
            
            // Get the vendor ID from the authenticated user
            const user = JSON.parse(localStorage.getItem('studioUser'));
            const vendorId = user?.vendor_id;
            
            if (!vendorId) {
                toast.error('Unable to load reels: User not authenticated');
                setLoading(false);
                return;
            }
            
            // Prepare filters for API call
            const apiFilters = {};
            if (appliedFilters.title) apiFilters.title = appliedFilters.title;
            if (appliedFilters.category) apiFilters.category = appliedFilters.category;
            if (appliedFilters.date) apiFilters.date = appliedFilters.date;
            if (appliedFilters.product) apiFilters.product = appliedFilters.product;
            if (appliedFilters.status) apiFilters.status = appliedFilters.status;
            
            console.log('Sending filters to API:', apiFilters);
            
            // Get seller reels from API with filters
            const response = await ApiService.getSellerReels(vendorId, apiFilters);
            
            if (response.success) {
                // Load product names for all reels
                await loadProductNames(response.data);
                
                // Set reels directly without grouping
                setReels(response.data);
                console.log('Received filtered reels:', response.data);
            }
            setLoading(false);
        } catch (error) {
            console.error('Error loading seller reels with filters:', error);
            toast.error('Failed to load reels: ' + error.message);
            setLoading(false);
        }
    };

    const handleFilter = async () => {
        setAppliedFilters({ ...filters });
        console.log('Applying filters:', filters);
        await loadSellerReelsWithFilters();
    };

    const handleClearFilter = async () => {
        const cleared = {
            title: '',
            category: '',
            date: '',
            product: '',
            status: ''
        };
        setFilters(cleared);
        setAppliedFilters(cleared);
        await loadSellerReels(); // Reload all reels
    };

    // Function to load product names from the database
    const loadProductNames = async (reelsData) => {
        console.log('Loading product names for reels:', reelsData);
        try {
            // Collect all unique product IDs from all reels
            const allProductIds = new Set();
            reelsData.forEach(reel => {
                if (reel.product_ids && Array.isArray(reel.product_ids)) {
                    reel.product_ids.forEach(id => {
                        // Ensure ID is a valid number before adding to set
                        const numericId = parseInt(id);
                        if (!isNaN(numericId) && numericId > 0) {
                            allProductIds.add(numericId);
                        }
                    });
                }
            });

            if (allProductIds.size === 0) {
                setProductNames({});
                return;
            }

            // Convert Set to Array of numbers
            const productIdsArray = Array.from(allProductIds);
            
            // Fetch real product names from the API
            const response = await ApiService.getProductNamesByIds(productIdsArray);
            if (response.success) {
                setProductNames(response.data);
            } else {
                // Fallback to placeholder names if API fails
                const productNamesMap = {};
                productIdsArray.forEach(id => {
                    productNamesMap[id] = `Product ${id}`;
                });
                setProductNames(productNamesMap);
            }
        } catch (error) {
            console.error('Error loading product names:', error);
            // Fallback to placeholder names if API fails
            const allProductIds = new Set();
            reelsData.forEach(reel => {
                if (reel.product_ids && Array.isArray(reel.product_ids)) {
                    reel.product_ids.forEach(id => {
                        const numericId = parseInt(id);
                        if (!isNaN(numericId) && numericId > 0) {
                            allProductIds.add(numericId);
                        }
                    });
                }
            });
            
            const productIdsArray = Array.from(allProductIds);
            const productNamesMap = {};
            productIdsArray.forEach(id => {
                productNamesMap[id] = `Product ${id}`;
            });
            setProductNames(productNamesMap);
        }
    };

    // Function to get product name for a reel
    const getProductNameForReel = (reel) => {
        if (reel.product_ids && Array.isArray(reel.product_ids) && reel.product_ids.length > 0) {
            const productId = parseInt(reel.product_ids[0]);
            if (!isNaN(productId) && productId > 0) {
                return productNames[productId] || `Product ${productId}`;
            }
        }
        return 'No Product Assigned';
    };

    const getStatusBadge = (status) => {
        switch (status) {
            case 1:
                return <span className="badge bg-success">Approved</span>;
            case 0:
                return <span className="badge bg-warning">Pending</span>;
            case 2:
                return <span className="badge bg-danger">Rejected</span>;
            default:
                return <span className="badge bg-secondary">Unknown</span>;
        }
    };

    // Calculate pagination outside of render
    const totalPages = Math.max(1, Math.ceil(reels.length / pageSize));
    const paginatedReels = reels.slice((currentPage - 1) * pageSize, currentPage * pageSize);

    return (
        <div className="row">
            <div className="col-12">
                <div className="page-title-box d-flex align-items-center justify-content-between">
                    <h4 className="page-title mb-0">All Reels</h4>
                </div>
            </div>

            <div className="col-12">
                <div className="card">
                    <div className="card-header d-flex align-items-center justify-content-between">
                        <h5 className="card-title mb-0">Reels List</h5>
                        <Link to="/studio/seller/upload" className="btn btn-success">
                            <i className="ri-add-line me-1"></i> Upload Reel
                        </Link>
                    </div>
                    <div className="card-body">
                        {/* Filter Section */}
                        <div className="row mb-3">
                            <div className="col-md-2">
                                <label className="form-label">Title</label>
                                <input
                                    type="text"
                                    className="form-control"
                                    placeholder="Filter by title"
                                    value={filters.title || ''}
                                    onChange={(e) => setFilters({...filters, title: e.target.value})}
                                />
                            </div>
                            <div className="col-md-2">
                                <label className="form-label">Category</label>
                                <input
                                    type="text"
                                    className="form-control"
                                    placeholder="Filter by category"
                                    value={filters.category || ''}
                                    onChange={(e) => setFilters({...filters, category: e.target.value})}
                                />
                            </div>
                            <div className="col-md-2">
                                <label className="form-label">Date</label>
                                <input
                                    type="date"
                                    className="form-control"
                                    value={filters.date || ''}
                                    onChange={(e) => setFilters({...filters, date: e.target.value})}
                                />
                            </div>
                            <div className="col-md-2">
                                <label className="form-label">Product</label>
                                <input
                                    type="text"
                                    className="form-control"
                                    placeholder="Filter by product"
                                    value={filters.product || ''}
                                    onChange={(e) => setFilters({...filters, product: e.target.value})}
                                />
                            </div>
                            <div className="col-md-2">
                                <label className="form-label">Status</label>
                                <select
                                    className="form-select"
                                    value={filters.status || ''}
                                    onChange={(e) => setFilters({...filters, status: e.target.value})}
                                >
                                    <option value="">All Statuses</option>
                                    <option value="1">Approved</option>
                                    <option value="0">Pending</option>
                                    <option value="2">Rejected</option>
                                </select>
                            </div>
                            <div className="col-md-2">
                                <label className="form-label">&nbsp;</label>
                                <div>
                                    <button 
                                        className="btn btn-primary me-2" 
                                        onClick={handleFilter}
                                    >
                                        Filter
                                    </button>
                                    <button 
                                        className="btn btn-secondary" 
                                        onClick={handleClearFilter}
                                    >
                                        Clear
                                    </button>
                                </div>
                            </div>
                        </div>
                        
                        {loading ? (
                            <div className="text-center py-5">
                                <div className="spinner-border" role="status">
                                    <span className="visually-hidden">Loading...</span>
                                </div>
                            </div>
                        ) : (
                            <>
                            <div className="table-responsive">
                                <table className="table table-hover align-middle mb-0">
                                    <thead>
                                        <tr>
                                            <th>Title</th>
                                            <th>Product</th>
                                            <th>Category</th>
                                            <th>Status</th>
                                            <th>Views</th>
                                            <th>Likes</th>
                                            <th>Date</th>
                                            <th>Actions</th>
                                        </tr>
                                    </thead>
                                    <tbody>
                                        {reels.length === 0 ? (
                                            <tr>
                                                <td colSpan="8" className="text-center py-5">No reels found</td>
                                            </tr>
                                        ) : paginatedReels.length === 0 ? (
                                            <tr>
                                                <td colSpan="8" className="text-center py-5">No reels match the current filters</td>
                                            </tr>
                                        ) : (
                                            paginatedReels.map((reel) => (
                                                <tr key={reel.id}>
                                                    <td className="text-truncate" style={{ maxWidth: '150px' }} title={reel.title}>
                                                        {reel.title}
                                                    </td>
                                                    <td>
                                                        {getProductNameForReel(reel)}
                                                    </td>
                                                    <td>{reel.category_name || 'Uncategorized'}</td>
                                                    <td>{getStatusBadge(reel.status)}</td>
                                                    <td>{reel.views || 0}</td>
                                                    <td>{reel.likes || 0}</td>
                                                    <td>{new Date(reel.created_at).toLocaleDateString()}</td>
                                                    <td>
                                                        <button 
                                                            className="btn btn-sm btn-info me-1"
                                                            onClick={() => navigate(`/studio/seller/upload/${reel.id}`)}
                                                            title="Edit Reel"
                                                        >
                                                            <i className="ri-edit-line"></i>
                                                        </button>
                                                        <button 
                                                            className="btn btn-sm btn-primary"
                                                            onClick={() => window.open(reel.video_url, '_blank')}
                                                            title="View Video"
                                                        >
                                                            <i className="ri-eye-line"></i>
                                                        </button>
                                                    </td>
                                                </tr>
                                            ))
                                        )}
                                    </tbody>
                                </table>
                            </div>
                            <div className="d-flex justify-content-between align-items-center mt-3">
                                <div className="text-muted">
                                    Showing {(currentPage - 1) * pageSize + 1} to {Math.min(currentPage * pageSize, reels.length)} of {reels.length} entries
                                </div>
                                <ul className="pagination mb-0">
                                    <li className={`page-item ${currentPage === 1 ? 'disabled' : ''}`}>
                                        <button className="page-link" aria-label="Previous" onClick={() => setCurrentPage(p => Math.max(1, p - 1))}>
                                            <i className="ri-arrow-left-s-line"></i>
                                        </button>
                                    </li>
                                    {Array.from({ length: totalPages }, (_, i) => i + 1).map(page => (
                                        <li key={page} className={`page-item ${page === currentPage ? 'active' : ''}`}>
                                            <button className="page-link" onClick={() => setCurrentPage(page)}>{page}</button>
                                        </li>
                                    ))}
                                    <li className={`page-item ${currentPage >= totalPages ? 'disabled' : ''}`}>
                                        <button className="page-link" aria-label="Next" onClick={() => setCurrentPage(p => Math.min(totalPages, p + 1))}>
                                            <i className="ri-arrow-right-s-line"></i>
                                        </button>
                                    </li>
                                </ul>
                            </div>
                        </>
                        )}
                    </div>
                </div>
            </div>
        </div>
    );
}
